# SaleHop: ad click destination + dead-ad-click fix
#
# What this fixes / adds:
#
#   THE BUG (what you reported): tapping an ad opened nothing. Root cause --
#   several ads (including the two thrift-shop ones you saw) were created
#   with no link_url on file, and the old AdCard.js only ever did
#   window.open(ad.link_url, ...) -- with no link, that's a no-op.
#
#   THE FIX (what you asked for): tapping an ad now opens the ad's own page
#   right inside SaleHop by default (salehop.app/ad/[id] -- already built
#   for the badges update, so it already shows the image, description, a
#   "Visit Website" button for the link, and -- for a physical location --
#   the address, an "I'm here!" check-in button, and Mayor standing). That
#   page is always reachable even when an ad has no link on file, which is
#   what actually closes the bug.
#
#   THE NEW OPTION: a "Link only" checkbox, on both the admin ad form and a
#   business's own "My Ad" editor. Leave it unchecked (the default, and
#   what every existing ad gets automatically) for the new in-app-page
#   behavior above. Check it for an ad that should skip its own page
#   entirely and jump straight to its link in a new tab instead -- the
#   original behavior, for a sponsor who just wants a direct click-through.
#
#   One database change: adds ads.link_only (defaults to false for every
#   ad you've already created, so nothing changes for them unless you go
#   check that box). Run this script, then run the SQL block it prints in
#   your Supabase SQL Editor (Project -> SQL Editor -> New query -> paste
#   -> Run) -- same as every past database update.
#
# Touches: supabase/schema-v15-ad-link-destination.sql (new),
# lib/dbCompat.js (new), components/AdCard.js, components/BrowseScreen.js,
# components/AdForm.js, components/AdOwnerForm.js,
# app/api/admin/ads/route.js, app/api/admin/ads/[id]/route.js,
# app/admin/page.js, app/admin/admin.module.css. No new npm package.

if (-not (Test-Path "package.json")) {
    Write-Host "ERROR: package.json not found. Run this script from inside your salehop project folder." -ForegroundColor Red
    exit 1
}
if (-not (Test-Path ".git")) {
    Write-Host "ERROR: .git folder not found. Run this script from inside your salehop project folder." -ForegroundColor Red
    exit 1
}

[System.IO.Directory]::SetCurrentDirectory((Get-Location).Path)


