cjogIzVhNTM0NjsKfQo=
"@
[System.IO.File]::WriteAllBytes("app/admin/admin.module.css", [Convert]::FromBase64String($b64_app_admin_admin_module_css))
Write-Host "Updated app/admin/admin.module.css"


$checkFiles = @(
    "supabase/schema-v15-ad-link-destination.sql",
    "lib/dbCompat.js",
    "components/AdCard.js",
    "components/BrowseScreen.js",
    "components/AdForm.js",
    "components/AdOwnerForm.js",
    "app/api/admin/ads/route.js",
    "app/api/admin/ads/[id]/route.js",
    "app/admin/page.js",
    "app/admin/admin.module.css"
)
$missing = $checkFiles | Where-Object { -not (Test-Path -LiteralPath $_) }
if ($missing) {
    Write-Host "ERROR: the following files did not get written:" -ForegroundColor Red
    $missing | ForEach-Object { Write-Host "  $_" -ForegroundColor Red }
    exit 1
}
Write-Host ""
Write-Host "All files written successfully." -ForegroundColor Green
Write-Host ""
Write-Host "ONE MORE STEP -- a database change is needed too:" -ForegroundColor Yellow
Write-Host "  1. Open your Supabase project -> SQL Editor -> New query" -ForegroundColor Yellow
Write-Host "  2. Paste and run the contents of:" -ForegroundColor Yellow
Write-Host "       supabase/schema-v15-ad-link-destination.sql" -ForegroundColor Yellow
Write-Host "  3. It's safe to run even if you're not sure -- it only adds one new column and does nothing if you run it twice." -ForegroundColor Yellow
Write-Host ""

git status

Write-Host ""
$answer = Read-Host "Commit and push these changes now? (Y/N)"
if ($answer -eq "Y" -or $answer -eq "y") {
    git add -A
    if ($LASTEXITCODE -ne 0) { Write-Host "ERROR: git add failed." -ForegroundColor Red; exit 1 }

    $commitMessage = @"
Fix dead ad clicks: open ad's own page by default, add link-only option

Co-Authored-By: Claude Sonnet 5 <noreply@anthropic.com>
Claude-Session: https://claude.ai/code/session_01146L7oDTraxR2XyGhaGyrm
"@

    $commitMsgFile = [System.IO.Path]::GetTempFileName()
    [System.IO.File]::WriteAllText($commitMsgFile, $commitMessage)
    git commit -F $commitMsgFile
    $commitExitCode = $LASTEXITCODE
    Remove-Item $commitMsgFile -ErrorAction SilentlyContinue
    if ($commitExitCode -ne 0) { Write-Host "ERROR: git commit failed." -ForegroundColor Red; exit 1 }

    git push
    if ($LASTEXITCODE -ne 0) { Write-Host "ERROR: git push failed." -ForegroundColor Red; exit 1 }

    Write-Host ""
    Write-Host "Done! Changes committed and pushed. Vercel should start deploying shortly." -ForegroundColor Green
    Write-Host "Don't forget the SQL Editor step above -- the code deploys either way, but the" -ForegroundColor Yellow
    Write-Host "new Link Only checkbox won't actually save until that column exists." -ForegroundColor Yellow
} else {
    Write-Host "Skipped commit/push. Your files were updated locally but not committed." -ForegroundColor Yellow
}
